import { AppShell, Button, ConsentCheckbox, Field } from "@wizard/ui-kit";
import { useEntityMutation, useState } from "@wizard/sdk";

export default function Main() {
  const [form, setForm] = useState({ name: "", phone: "", consent: false });
  const requests = useEntityMutation("request");
  return (
    <AppShell title={"Оптовая обжарка кофе: CRM кофеен, заказы по графику и дебиторка"}>
      <p>{"Мы небольшая обжарочная в Калининграде, поставляем зерно и дрип-пакеты в кофейни и офисы области, около семидесяти постоянных клиентов. Всё в таблицах и мессенджерах, менеджеры путают цены и забывают про долги. Нужна админ-система: карточка клиента (кофейня или офис, адрес доставки, свой прайс и отсрочка платежа), каталог сортов с ценой за килограмм, заказы со статусами «новый», «собран», «отгружен», «доставлен», «оплачен». Часть клиентов берёт кофе по графику, например каждый вторник, — такие заказы система создаёт сама, менеджер только подтверждает. Видно, кто сколько должен и у кого просрочена оплата. Кладовщик видит заказы к сборке на завтра и отмечает сборку, водитель — свой маршрут на день. Менеджер ведёт своих клиентов, руководитель видит всё и отчёт за месяц: выручка по клиентам и сортам, долги. Связь с поставщиками зелёного зерна держит клиент, его номер клиент. Требования к отчётам прикладываю файлом."}</p>
      <ul>
        <li>{"Статусы заказа"}</li>
        <li>{"Заказы по графику"}</li>
        <li>{"Долги и просрочка"}</li>
        <li>{"Индивидуальный прайс"}</li>
        <li>{"Отчёт за месяц"}</li>
      </ul>
      <p>{"Менеджер видит только своих клиентов"}</p>
      <p>{"Кладовщик не видит цены"}</p>
      <form onSubmit={(e) => { e.preventDefault(); void requests.create({ contact_name: form.name, contact_phone: form.phone }, { consent: true }); }}>
        <Field name="contact_name" label="Имя" type="string" value={form.name} onChange={(v) => setForm({ ...form, name: String(v) })} />
        <Field name="contact_phone" label="Телефон" type="phone" value={form.phone} onChange={(v) => setForm({ ...form, phone: String(v) })} />
        <ConsentCheckbox checked={form.consent} onChange={(v) => setForm({ ...form, consent: v })} />
        <Button type="submit">{"Отправить заявку"}</Button>
      </form>
    </AppShell>
  );
}
